from .facade import DiagnosticCardFacade
from taf.config.testline import RU
from typing import Union, List, Dict


class rf_diagnostic_card:
    """
    The `rf_diagnostic_card` library provides an API for interacting with RMODs via LMI, LmiLight or MUMIN cards.
    Example declaration in Python test file for each of Diagnostic Card types can be found
    `in this example <https://taf-hw-rf-diagnostic-card.docs.taf.ute.nsn-rdnet.net/en/latest/example/\
    example.html#python-example-with-all-diagnostic-card-object-types>`_

    It enables users to:
     - **Save serial console logs**, which are started automatically after RMOD connection
       with the `setup_connections` method. Serial logs are stored by default in the temporary directory
       and saved to the main log directory when disconnecting the RMOD or manually, anytime when possible,
       using the `download_log` method.
     - **Automatically execute commands** - read from the `connection_setup` parameter of the
       `YAML <https://taf-hw-rf-diagnostic-card.docs.taf.ute.nsn-rdnet.net/en/latest/example/\
       example.html#custom-library-behaviour-setup-with-yaml-file>`_ file
       automatically after successful log in or RMOD startup.
       Possible `YAML <https://taf-hw-rf-diagnostic-card.docs.taf.ute.nsn-rdnet.net/en/latest/example/\
       example.html#custom-library-behaviour-setup-with-yaml-file>`_
       keys for commands definition are:

       - **send_commands_after_connect** - list of commands to be sent after successful connection to the RMOD.
       - **send_commands_after_login_master** - list of commands to be sent after RMOD startup
         and successful login to the master node.
       - **send_commands_after_login_slave** - list of commands to be sent after RMOD startup
         and successful login to the slave node.

     - **Automatically or manually switch nodes** to collect other nodes startup serial console logs.
       First slave node id is randomized and after each RMOD restart the next slave node is selected
       with the 'round-robin' algorithm.
       Possible `YAML <https://taf-hw-rf-diagnostic-card.docs.taf.ute.nsn-rdnet.net/en/latest/example/\
       example.html#custom-library-behaviour-setup-with-yaml-file>`_
       keys for automatic switch behaviour change are:

       - **switch_nodes** - if set to True (default), then serial console will be automatically switched
         to the slave node (if possible for RMOD family) after each RMOD restart and successful connection to the RMOD.
       - **switch_slave_node_id** - if set, then serial console will be switched to the slave node with the given id
         for the first time after RMOD reset.
       - **node_switch_seconds** - time in seconds to wait for the node switch to complete and back to the master node.
       - **freeze_slave_node_switch** - if set to True, then the serial console will be switched to the slave node that
         was selected by the `switch_slave_node_id` key or selected randomly from available slave nodes and will not
         be switched to the next slave node.

     - **Collect RMOD snapshot** and save it in non-volatile memory and other logs from debug commands.
       Snapshot may be taken manually using the `take_snapshot` method, or it is set to be taken automatically
       after RMOD connection setup, if the `auto_snapshot_on_fault` key is set to True in the YAML file.
       Automatic snapshot is taken only if declared internal RMOD faults are detected on the RMOD.
       The default declared faults are: critical:**1112, 10004, 1384, 1149, 1103, 1255, 1288, 1405, 1463**
       and other faults: **1309** if visible **twice**. Fault checks in the fault history log are performed
       **every 1 minute**.
       `YAML <https://taf-hw-rf-diagnostic-card.docs.taf.ute.nsn-rdnet.net/en/latest/example/\
       example.html#custom-library-behaviour-setup-with-yaml-file>`_
       keys for auto snapshot or manual snapshot configuration are:

       - **auto_snapshot_on_fault** - if set to True (default), then snapshot will be taken automatically
       - **critical_faults_to_snapshot_list** - list of critical faults to trigger snapshot creation.
       - **normal_faults_to_snapshot_dict** - dictionary with fault ID as a key and number of detections
         of a fault with the same timestamp as a value for normal faults to trigger snapshot creation.
       - **proxy_vm** - if set, then it defines the proxy VM address to use in BTS+BTS setups,
         where direct SSH connection from local VM via SMOD to the RMOD is not possible.
         Proxy VM address and username may be also set using the `set_proxy_vm_address_and_username` method.
         The dictionary may contain the following keys:

         - **ip** - if set, then it defines the proxy SSH VM IP address to use in BTS+BTS setups,
           where direct SSH connection from local VM via SMOD to the RMOD is not possible.
         - **username** - username for the proxy VM. Defaults to "ute", which is the default username
           for the VMs provided by UTE. This feature only works with SSH login via key, so no password
           authentication is supported.

       .. note::
          - The snapshot is saved in the non-volatile memory of the RMOD only if there is enough space available
            and nothing wrong happened during the snapshot creation and moving to ROM.
            If the snapshot is saved in the non-volatile memory of the RMOD, it will be removed
            at the beginning of the next `setup_connections` function call (new connection to the same RMOD
            or new testcase run). Check /mnt/runtime/snapshot and /mnt/runtime/auto_snapshot directories
            on the RMOD before calling the method.
          - In case of BTS+BTS setups, where direct SSH connection from local VM via SMOD to the RMOD is not possible,
            the proxy VM address and username must be set either in the YAML file or using the
            `set_proxy_vm_address_and_username` method just after successful connection with the serial
            console to the RMOD before calling the `take_snapshot` method or passed as parameters to the method.

     - **Automatically create a file preserving RMOD flags** - this file is created automatically after each RMOD
       reset. This behaviour can be disabled by setting the `preserve_flags` key to False in the
       `YAML <https://taf-hw-rf-diagnostic-card.docs.taf.ute.nsn-rdnet.net/en/latest/example/\
       example.html#custom-library-behaviour-setup-with-yaml-file>`_ file.
     - **Send or execute commands** on RMODs using the `send_command` or `execute_command` methods.
     - **Download saved snapshot** from ROM after RMOD recovery (e.g., when FID:10 visible for the RMOD)

     More examples for Python or Robot Framework can be found
     `here <https://taf-hw-rf-diagnostic-card.docs.taf.ute.nsn-rdnet.net/en/latest/example/example.html#>`_

    """

    ROBOT_LIBRARY_SCOPE = "TEST SUITE"

    def __init__(self):
        """
        Initialize the RF Diagnostic Card library.
        """
        self._diagnostic_card = DiagnosticCardFacade()

    def prepare_log_directory_and_connection_setup(
        self, main_log_directory: str, connection_setup: Union[str, None] = None
    ):
        """
        Prepares the log directory and custom connection setup for the RF Diagnostic Card.
        In this directory, the library will create subdirectories for each RMOD connection and save logs from
        the serial console and snapshots taken from the RMODs if behaviour is not changed by the user.
        The library log will allways be saved in the proper subdirectory of the main log directory.

        .. note::
            After the changes introduced in feature CB0010663 related to disabling the 'rfsw' account,
            it became necessary to differentiate the radio interface to retrieve the correct credentials
            for logging into the RMOD. The default interface is None, which means that RMOD credentials are read
            from taf.config.testline for given RMOD Family, and in case of an error related
            to an incorrect username or password during the connection, the `fh_interface` key should
            be used in the `YAML <https://taf-hw-rf-diagnostic-card.docs.taf.ute.nsn-rdnet.net/en/latest/example/\
            example.html#custom-library-behaviour-setup-with-yaml-file>`_ file for the given RMOD.
            Possible values for the `fh_interface` key are (case-sensitive):

            - **eCPRI** - used for RMODs that support eCPRI interface.
            - **CPRI** - used for RMODs that support CPRI interface.
            - **OBSAI** - used for RMODs that support OBSAI interface.

        :param str main_log_directory: The main directory for logs from all RUs.
        :param str/None connection_setup: Path to the custom setup YAML file for RUs connections. Defaults to None,
                                          which means the default setup will be used.
        :return: None
        """
        self._diagnostic_card.prepare_log_directory_and_connection_setup(
            main_log_directory=main_log_directory, connection_setup=connection_setup
        )

    def setup_connections(
        self,
        ru_config: Union[RU, List[RU]],
        alias: str = None,
        log_to_console: bool = False,
        ignore_exceptions: bool = False,
        use_init_credentials: bool = False,
        **kwargs,
    ) -> List[Union[str, int]]:
        """
        Setups the connections for the RF Diagnostic Card.
        From this moment, the library will start collecting logs from the serial console and starts waiting
        for raised faults in the RMODs. Serial console logs are saved in the temporary directory, but are
        moved to the main log directory when disconnecting the RMOD or manually, anytime when possible,
        using the `download_log` method.

        :param RU/list[RU] ru_config: RMOD configuration from the testline init file.
                                        It may be single RU or list of RUs. If list is provided, then alias is ignored.
        :param str alias: Alias for the connection.
                          Defaults to None, which means that RMOD serial number is used as alias.
        :param log_to_console: Flag to log library outputs to console.
        :param bool ignore_exceptions: Flag to ignore exceptions during connection setup.
                                       May be useful when list of RUs is given for connection setup.
                                       Defaults to False, which means exceptions will be raised
                                       in case of serial console connection failure.
        :param kwargs: Additional parameters to set up resources needed for Pyro server connection that are passed
                       to the `setup_host` method of the `rmod_serial_interface` library.
                       For more details and the current list of supported parameters
                       see `the "setup_host" method documentation <https://taf-hw-rmod-serial-\
                       interface.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/interface.html#taf.hw.\
                       rmod_serial_interface.interface.rmod_serial_interface.setup_host>`_
        :param bool use_init_credentials: Flag to use RMOD credentials from the testline init file.
                                         If set to True, then RMOD credentials will be read from the testline init file
                                         for the given RMOD family instead of using credentials from
                                         taf.config.testline or default credentials defined in the library.
                                         Defaults to False. This parameter requires that the RU object
                                         has the `default_ssh_connection_details` attribute set with
                                         proper SSH connection details. For details see the `example with credentials
                                         <https://taf-hw-rf-diagnostic-card.docs.taf.ute.nsn-rdnet.net/en/latest/
                                         example/example.html#python-example-with-own-ru-object-with-serialovertcp>`_
        :return: list - list of aliases. If single RU and alias provided then list will contain a list
                        with single alias that could be an RMOD ID (string or integer) or serial number (string).
                        In case of multiple RUs, the list will contain aliases for each RMOD and it always be
                        a list of strings (serial numbers). Any alias provided if the `ru_config` takes a list
                        will be ignored.
        """
        return self._diagnostic_card.setup_connections(
            ru_config=ru_config,
            alias=alias,
            log_to_console=log_to_console,
            ignore_exceptions=ignore_exceptions,
            use_init_credentials=use_init_credentials,
            **kwargs,
        )

    def take_snapshot(
        self,
        alias: str,
        target_path_on_vm: Union[str, None] = None,
        reset_rmod: bool = False,
        stop_and_fix: bool = False,
        skip_downloading: bool = False,
        timeout: int = 180,
        proxy_vm_address: str = None,
        proxy_vm_username: str = "ute",
    ) -> bool:
        """
        Take a snapshot from the connected RMOD.

        :param str alias: Alias of the connection.
        :param str/None target_path_on_vm: Path to save the snapshot on VM.
                                           Defaults to None, which means the main_log_directory will be used.
        :param bool reset_rmod: Flag to reset the RMOD.
                                If snapshot is not moved to ROM and the flag was set to True, then RMOD
                                will NOT be reset, to give a chance to download the snapshot manually from RAM.
        :param bool stop_and_fix: Flag to stop and fix. It blocks RMOD reset if requested in the previous parameter.
        :param bool skip_downloading: Flag to skip downloading the snapshot to VM.
                                      If snapshot file is not moved to ROM it tries to download from RAM
                                      (if file created).
        :param int timeout: Timeout for the operation.
        :param str/None proxy_vm_address: Address of the proxy VM to use in BTS+BTS setups.
                                          If None, then connection to the RMOD is set up from the local VM or with the
                                          address set with the yaml file or `set_proxy_vm_address_and_username` method.
                                          This way it allows to download snapshot file via alternative SSH connection.
        :param str proxy_vm_username: Username for the proxy VM. Defaults to "ute", which is the default username
                                      for the VMs provided by UTE. This feature only works with SSH login via key,
                                      password authentication is not supported.
        :return: bool - True if successful, False otherwise.
        """
        return self._diagnostic_card.take_snapshot(
            alias=alias,
            target_path_on_vm=target_path_on_vm,
            reset_rmod=reset_rmod,
            stop_and_fix=stop_and_fix,
            skip_downloading=skip_downloading,
            timeout=int(timeout),
            proxy_vm_address=proxy_vm_address,
            proxy_vm_username=proxy_vm_username,
        )

    def download_snapshot(
        self,
        alias: str,
        target_path_on_vm: Union[str, None] = None,
        proxy_vm_address: str = None,
        proxy_vm_username: str = "ute",
    ) -> bool:
        """
        Download snapshot, which was already taken, from the RMOD.

        :param str alias: Alias of the connection.
        :param str/None target_path_on_vm: Path to save the snapshot on VM.
                                           Defaults to None which means the main_log_directory will be used.
        :param str/None proxy_vm_address: Address of the proxy VM to use in BTS+BTS setups.
                                          If None, then connection to the RMOD is set up from the local VM or with the
                                          address set with the yaml file or `set_proxy_vm_address_and_username` method.
                                          This way it allows to download snapshot file via alternative SSH connection.
        :param str proxy_vm_username: Username for the proxy VM. Defaults to "ute", which is the default username
                                      for the VMs provided by UTE. This feature only works with SSH login via key,
                                      password authentication is not supported.
        :return: bool - True if successful, False otherwise.
        """
        return self._diagnostic_card.download_snapshot(
            alias=alias,
            target_path_on_vm=target_path_on_vm,
            proxy_vm_address=proxy_vm_address,
            proxy_vm_username=proxy_vm_username,
        )

    def reset_rmod(self, alias: str, wait_time: int = 100):
        """
        Reset the RMOD.

        :param str alias: Alias of the connection.
        :param int wait_time: Time to wait for the reset to complete. Defaults to 100 seconds.
        :return: None
        """
        self._diagnostic_card.reset_rmod(alias=alias, wait_time=int(wait_time))

    def switch_serial_to_node(self, alias: str, node: int) -> bool:
        """
        Switches serial output to desired node in runtime.
        It should be called with node id accordingly to the `Logging capability - platforms overview
        <https://confluence.ext.net.nokia.com/display/RFSW/Logging+capability+-+platforms+overview>`_ documentation.

        :param str alias: Alias of the connection
        :param int node: Node id to switch.

                           * For 5.1 generation RMODs, allowed values are 0 and 1 (0 - Master, 1 - Slave)
                           * For Scorpio, allowed values are 0,1,2 (0 - Master, 1 - Made1, 2 - Made2)
                           * For Chile RMODs, allowed value is from range 0-9 (0 - Master, 1 - Stratix1, 2 - DFE0,
                             ... 9 - DFE7)
                           * For 7.1 generation RMODs, allowed values are 0 and 1-3 (0 - Master, 1-3 - Slaves).
                             The one exception for 7.1 family is Fisto, which has 2xMars nodes.
                             Switch command will not be executed when serial console is connected to Thor node.

        :return: bool - True if preparing a switch command was possible and the command was sent, False otherwise
        """
        return self._diagnostic_card.switch_serial_to_node(alias=alias, node=int(node))

    def set_proxy_vm_address_and_username(self, alias: str, proxy_vm_address: str, proxy_vm_username: str = "ute"):
        """
        Sets the proxy VM address and username for the RF Diagnostic Card library to use in the BTS+BTS setups,
        where direct SSH connection from local VM via SMOD to the RMOD is not possible.

        :param str alias: Alias of the connection.
        :param str proxy_vm_address: Address of the proxy VM.
        :param str proxy_vm_username: Username for the proxy VM. This feature only works with SSH login via key,
                                      password authentication is not supported.
        :return: None
        """
        self._diagnostic_card.set_proxy_vm_address_and_username(
            alias=alias, proxy_vm_address=proxy_vm_address, proxy_vm_username=proxy_vm_username
        )

    def set_rmod_credentials(self, alias: str, password: str, username: str = "serviceuser"):
        """
        Sets the RMOD credentials for the RF Diagnostic Card library to use during connection setup
        or 'actSyncToRU' flag is in use and the 'serviceuser' account password is synchronized from SMOD to RMOD.

        :param str alias: Alias of the connection.
        :param str password: RMOD password.
        :param str username: RMOD username. Defaults to 'serviceuser'.
        :return: None
        """
        self._diagnostic_card.set_rmod_credentials(alias=alias, password=password, username=username)

    def get_rmod_ip(self, alias: str, wait_time: int = 120) -> Union[str, list[str], None]:
        """
        Gets the RMOD IP address.
        If the IP address is not (yet) available, by default, it will try to get the IP for 2 minutes (blocking call).

        :param str alias: Alias of the connection.
        :param int wait_time: Time to wait for the IP address to be available. Defaults to 120 seconds.
        :return: str/list[str]/None - RMOD IP address or list of addresses in case of RF Sharing configuration
                                      or None if IP(s) couldn't be found.
        """
        return self._diagnostic_card.get_rmod_ip(alias=alias, wait_time=wait_time)

    def get_rmod_serial_number(self, alias: str) -> str:
        """
        Gets the RMOD serial number.

        :param str alias: Alias of the connection.
        :return: str - RMOD serial number.
        """
        return self._diagnostic_card.get_rmod_serial_number(alias=alias)

    def get_rmod_snapshot_path(self, alias: str) -> Union[str, None]:
        """
        Gets the path to the RMOD snapshot.

        :param str alias: Alias of the connection.
        :return: str/None - Path to the RMOD snapshot.
                 If snapshot was not collected and saved on ROM then None is returned.
        """
        return self._diagnostic_card.get_rmod_snapshot_path(alias=alias)

    def download_log(self, alias: str, target_filepath: str):
        """
        Download the log from the RF Diagnostic Card.

        :param str alias: Alias of the connection.
        :param target_filepath: Path to save the log on VM.
        :return: None
        """
        self._diagnostic_card.download_log(alias=alias, target_filepath=target_filepath)

    def create_file_preserving_rmod_flags(self, alias: str):
        """
        Creates a file preserving the current state of the Rmod flags.

        :param str alias: Alias of the connection.
        :return: None
        """
        self._diagnostic_card.create_file_preserving_rmod_flags(alias=alias)

    def execute_command(
        self,
        alias: str,
        cmd: str,
        elevated: bool = False,
        wait_time: int = 30,
        write_output_to_logs: bool = True,
        as_rfsw: bool = True,
    ) -> str:
        """
        Execute a command on the RF Diagnostic Card.

        :param str alias: Alias of the connection.
        :param str cmd: Command to execute.
        :param bool elevated: Flag for elevated privileges.
        :param int wait_time: Wait time for the command to execute. Defaults to 30 seconds.
        :param bool write_output_to_logs: Flag to write output to logs.
        :param bool as_rfsw: Flag to execute command as rfsw user. Defaults to True.
                             Flag is ignored for RMODs that do not support 'serviceuser' and 'rfsw' users.
        :return: str - Command execution result.
        """
        return self._diagnostic_card.execute_command(
            alias=alias,
            cmd=cmd,
            elevated=elevated,
            wait_time=wait_time,
            write_output_to_logs=write_output_to_logs,
            as_rfsw=as_rfsw,
        )

    def send_command(self, alias: str, cmd: str, as_rfsw: bool = True):
        """
        Send a command to the RF Diagnostic Card.

        :param str alias: Alias of the connection.
        :param str cmd: Command to send.
        :param bool as_rfsw: Flag to execute command as rfsw user. Defaults to True.
                             Flag is ignored for RMODs that do not support 'serviceuser' and 'rfsw' users.
        :return: None
        """
        self._diagnostic_card.send_command(alias=alias, cmd=cmd, as_rfsw=as_rfsw)

    def disconnect(self, alias: str):
        """
        Disconnect the RF Diagnostic Card.

        :param str alias: Alias of the connection.
        :return: None
        """
        self._diagnostic_card.disconnect(alias=alias)

    def disconnect_all_rmods(self):
        """
        Disconnect all RMOD connections.

        :return: None
        """
        self._diagnostic_card.disconnect_all_rmods()

    def disconnect_all_rmods_and_shutdown(self, host_connections: Union[str, List[str], None] = None):
        """
        Disconnect all RMOD connections and shuts down server running on host machine.
        Use very carefully !
        It may shut down the server for other users who might be using it to collect logs from other RMODs.
        Preferably use one of the other 'disconnect' keywords and leave the server running,
        as it may be shut down manually later.

        :param str/list[str]/None host_connections: Host connections to teardown if any.
                                                    By default, this parameter value is set by rmod_serial_interface to
                                                    host connection address value when connecting to the RU.
                                                    If list is provided, only those connections will be torn down.
                                                    If string is provided, it will be treated as a single connection.
                                                    Defaults to None which means all connections will be torn down.
        :return: None
        """
        self._diagnostic_card.disconnect_all_rmods_and_shutdown(host_connections=host_connections)

    @property
    def rmod_connections(self) -> Dict:
        """
        Get all connected RUs.

        :return: dict - connected RUs with aliases as keys.
        """
        return self._diagnostic_card.rmod_connections
